use std::{collections::BTreeMap,fs};
fn main(){let mut rows=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/root-action/CONTROL.tsv").unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();assert_eq!(v.len(),8);let k:Vec<u64>=v[..6].iter().map(|x|x.parse().unwrap()).collect();let a:Vec<u64>=v[7].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(a.len(),16);assert_eq!(a[8],2*a[7]+a[5]+a[6]);let value=(v[6].to_string(),a);if k[3]==1{let mut z=k.clone();z[3]=0;assert_eq!(rows[&z],value)}assert!(rows.insert(k,value).is_none());}assert_eq!(rows.len(),80);println!("g\tp\tsm\tmodulus\told_REDC\tnew_REDC\told_over_new_REDC");for(k,(_,a))in &rows{if k[3]!=0||k[4]!=0{continue}let mut z=k.clone();z[4]=1;let(l,b)=&rows[&z];assert_eq!(&rows[k].0,l);println!("{}\t{}\t{}\t{}\t{}\t{}\t{:.6}",k[0],k[1],k[2],k[5],a[8],b[8],a[8]as f64/b[8]as f64)}eprintln!("records=80 same_eigenvalues=true repetitions=true REDC_identity=true");}
